corrected_code:
package graph

import (
	"context"
	"errors"
	"myapp/auth"
	"myapp/graph/model"
)

func (r *QueryResolver) DocumentExportJob(ctx context.Context, jobID string) (*model.ExportJob, error) {
	callerID := auth.GetUserID(ctx)
	job, err := r.JobStore.GetJob(ctx, jobID)
	if err != nil {
		return nil, err
	}

	if job.CreatedByUserID != callerID {
		return nil, errors.New("export job does not belong to authenticated user")
	}

	return job, nil
}
